/* general colors */
a:not(.nocolor) {color:orange;}
a.nocolor{color:#fff} 

html {
    background-size: cover; 
    background-position: 75% top;
    background-repeat: no-repeat;
    background-attachment: fixed;
}

.sub_list_item, .background_reply, .sub_list {
    background: #f3f3f3;
    color: #666;
}
.ad_box,.ad_box_dark,.ad_box_private{background:#dddddd;color:#000}
button { background:transparent; color:#fff; }
input, textarea, .post_input_container { background:rgba(0, 0, 0, 0); color:#666; }


