#intro_section_user { background:#fff; }

/* back mains colors */
.back_theme { background:#03add8; color:#fff; }
.back_dark { background:#012832; color:#fff; }

/* button colors */
.theme_btn { background:#03add8; color:#fff; }
.default_btn { color:#fff; }
.dark_selected { background:#03add8; color:#fff; }
.ok_btn { background:#74b20e; color:#fff; }
.warn_btn { background:orange; color:#fff; }
.delete_btn { background:#cc0000; color:#fff; }
.not_member { background:#999; color:#fff; }

/* input option background colors */
/*.input_item { color:#999; }*/

/* background colors */
.background_header, .chat_head, .chat_footer, .top_background, .panel_top, .emo_head, .modal_top { color:#fff; }
.background_box {background: rgba(255, 255, 255, 0);color:#666;}

/* modal */
.modal_menu { background:#ededed; color:#666; }
.modal_selected,.tab_selected{background:#012832;color:#fff}
.modal_back { background-color:rgba(0,0,0,0.3); }

/* menu icon */
/*.menu_icon, .menui, .pagemenui { color:#03add8; }*/

/* outside menu */
.sub_menu_item,.avitem{border-bottom:1px solid #ededed;background:#fff;color:#666}
.sub_menu_item:hover,.sub_menu_item:hover > .sub_menu_icon,.avitem:hover{background:#ededed;color:#666}

.sub_menu {background: rgba(255, 255, 255, 1);color:#666;}
.sub_menu li { border-bottom:0px solid #ededed; }
.sub_menu li:hover { background:#ededed; color:#666; }

/* inside menu */
.sub_menu_in { background:rgba(0, 0, 0, 0.05); }
.sub_menu_in li:hover, .status_option:hover { color:#666;}
.sub_menu_in li, .status_option { border-top:1px solid rgba(0, 0, 0, 0.05); }

/* page menu */
.pmenu{ border-bottom:1px solid #ededed; }
.pmenu:hover, .pmenu:hover > .pagemenui { background:#ededed; color:#666; }

/* text error colors */
.error { color:red; }
.success { color:#74b20e; }
.warn { color:orange; }

/* logs color private and main chat */
.target_private {color:#fff; background:#333;}
.target_private a { color:orange; }
.hunter_private {color:#fff; background:#03add8;}
.hunter_private a { color:#fff; }

/* text color  & date */
.sub_text, .date, .room_center, .help_text { color:#888; }
.input_text, .delete_log, .logs_date, .report_log, .pdate, .ptdate, .search_label { color:#888888; }
