.user_count  { color:#03add8; background: rgba(0, 0, 0, 0.05);}
 .my_notice{background:#ff9;color:#000;padding:0}
.shadow_text { text-shadow:1px 1px #000; }

/* notification colors */
.bnotify { background:red; color:#fff; }

/* elements */ 
.element_color, .page_element, #private_box, .page_menu ul, .chat_side_panel,
#side_menu, .room_content, .modal_in, .player_options { background:rgba(255, 255, 255, 1); color: #444; }
