@media only screen and (max-width: 480px) {
    #right_panel_bar {background-color: rgba(0, 0, 0, 0.05); height: 40px; }
}

#main_input_extra,#priv_input_extra {
    background-color: white;
}

rtl.css:
.no_rtl,.sp_top{direction:ltr}
.rtl_elem{direction:rtl}
.rtl_fright{float:right}
.rtl_fleft{float:left}
.rtl_aleft{text-align:left}
.rtl_aright{text-align:right}
.rtl_toright{left:auto;right:0}
.rtl_toleft{right:auto;left:0}
textarea,input{direction:rtl}
.selectboxit-arrow-container{position:absolute;left:0!important;right:auto}
.selectboxit-container .selectboxit-options{text-align:right}
.selectboxit-option-icon-container,.selectboxit-text{float:right}
.small_modal_content,.large_modal_content,.list_element,.drop_list,.page_element,.hunter_private,.target_private,#show_chat,.post_element,.news_element,.sub_menu,.menu_page,.user_item,.intro_footer,.sub_list_item,.user_count,.in_room_element,.listing_element,.sub_menu_item,.over_modal_content,.over_emodal_content{direction:rtl}
.p_item{float:right}
.profile_close{right:auto;left:0}
.like_count,.unlike_count{float:right;margin-right:0;margin-left:15px}
.comment_count{text-align:left;padding-left:10px;padding-right:0}
.my_text{padding:0 6px 0 0}
.chat_rank{padding:0 0 0 2px}
.room_counter{text-align:left}
.room_box{direction:rtl}
.room_options{direction:rtl}
.profile_cover_controls { position:absolute; bottom:0; right:auto; left:0; padding:10px 15px; font-size:20px; z-index:2; cursor:pointer;}
.topav_default { margin-right: 17px; }
